const trigger = $('Error Trigger').first().json || {};
const config = $input.first().json || {};
const execution = trigger.execution || {};
const workflow = trigger.workflow || {};
const err = execution.error || {};

function redact(input) {
  return String(input || 'Unknown error')
    .replace(/\bBearer\s+[A-Za-z0-9\-._~+/]+=*/gi, 'Bearer [REDACTED]')
    .replace(/\beyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\b/g, '[REDACTED]')
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[REDACTED]')
    .slice(0, 300);
}

const workflowName = String(workflow.name || 'Unknown Workflow');
const workflowId = String(workflow.id || 'unknown');
const executionId = String(execution.id || 'unknown');
const lastNode = String(execution.lastNodeExecuted || 'unknown');
const errorName = String(err.name || 'Error');
const sanitizedMessage = redact(err.message);

return [
  {
    json: {
      fromEmail: config.fromEmail,
      opsAlertEmail: config.opsAlertEmail,
      subject: `[LendLoop Ops] Workflow error in ${workflowName}`,
      text: [
        'An unhandled n8n workflow error occurred (PII stripped):',
        `Workflow: ${workflowName} (${workflowId})`,
        `Execution ID: ${executionId}`,
        `Last Node: ${lastNode}`,
        `Error Type: ${errorName}`,
        `Summary: ${sanitizedMessage}`,
      ].join('\n'),
    },
  },
];
